  'Frame data must be a number array or base64 float32': ['帧数据必须为数字数组或base64 float32', 'Dữ liệu khung phải là mảng số hoặc base64 float32', 'Data frame harus berupa array angka atau base64 float32', 'Les données de trame doivent être un tableau numérique ou du base64 float32', 'Los datos de la trama deben ser un arreglo numérico o base64 float32'],
  'Frame header needs shape [rows, cols]': ['帧头需要shape [rows, cols]', 'Phần đầu khung dữ liệu cần shape [rows, cols]', 'Header frame memerlukan shape [rows, cols]', 'L’en-tête de trame nécessite shape [rows, cols]', 'La cabecera de la trama necesita shape [rows, cols]'],
  'Frame payload too short': ['帧载荷过短', 'Dữ liệu khung quá ngắn', 'Payload frame terlalu pendek', 'Données de trame trop courtes', 'Contenido de la trama demasiado corto'],
  'Not a TRF1 binary frame': ['不是TRF1二进制帧', 'Không phải khung nhị phân TRF1', 'Bukan frame biner TRF1', 'Ce n’est pas une trame binaire TRF1', 'No es una trama binaria TRF1'],
  'The user did not select a port.': ['用户未选择端口。', 'Người dùng chưa chọn cổng.', 'Pengguna tidak memilih port.', 'Aucun port sélectionné par l’utilisateur.', 'El usuario no seleccionó un puerto.'],
