  'Where things are': ['目标位置', 'Vị trí vật thể', 'Lokasi objek', 'Position des objets', 'Posición de los objetos'],
  'Tiny motion': ['微小动作', 'Chuyển động rất nhỏ', 'Gerakan sangat kecil', 'Micromouvements', 'Micromovimientos'],
